#!/usr/bin/env bash
# Build the LeitnerFlow user documentation HTML export.
#
# Markdown remains the source of truth, following eLeDia.OS_DevFlow. The HTML
# file generated by this script is a delivery artefact for preview, handover, or
# publication.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PLUGIN_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"

SOURCE="${PLUGIN_DIR}/docs/02-user-doc.md"
TARGET="${PLUGIN_DIR}/docs/user-doc.html"
CSS="${PLUGIN_DIR}/docs/user-doc.css"

if [[ ! -f "${SOURCE}" ]]; then
    echo "ERROR: source file not found: ${SOURCE}" >&2
    exit 2
fi

if command -v pandoc >/dev/null 2>&1; then
    pandoc "${SOURCE}" \
        --from markdown \
        --to html5 \
        --standalone \
        --toc \
        --toc-depth=3 \
        --metadata title="LeitnerFlow Benutzer-Dokumentation" \
        --css "user-doc.css" \
        --output "${TARGET}"

    echo "Built ${TARGET} with pandoc"
    exit 0
fi

if ! command -v php >/dev/null 2>&1; then
    echo "ERROR: either pandoc or php is required to build ${TARGET}." >&2
    echo "Install pandoc for the best HTML export, for example: brew install pandoc" >&2
    exit 2
fi

php -d detect_unicode=0 -r '
$source = $argv[1];
$target = $argv[2];
$lines = file($source, FILE_IGNORE_NEW_LINES);

function lf_inline(string $text): string {
    $text = htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, "UTF-8");
    $text = preg_replace("/\*\*([^*]+)\*\*/", "<strong>$1</strong>", $text);
    $text = preg_replace("/`([^`]+)`/", "<code>$1</code>", $text);
    return $text;
}

function lf_slug(string $text, array &$used): string {
    $slug = strtolower($text);
    $slug = preg_replace("/[^a-z0-9]+/", "-", $slug);
    $slug = trim($slug, "-");
    if ($slug === "") {
        $slug = "section";
    }
    $base = $slug;
    $i = 2;
    while (isset($used[$slug])) {
        $slug = $base . "-" . $i;
        $i++;
    }
    $used[$slug] = true;
    return $slug;
}

$html = [];
$toc = [];
$used = [];
$paragraph = [];
$list = null;
$table = [];

$flushParagraph = function () use (&$html, &$paragraph): void {
    if (!$paragraph) {
        return;
    }
    $html[] = "<p>" . lf_inline(implode(" ", $paragraph)) . "</p>";
    $paragraph = [];
};

$flushList = function () use (&$html, &$list): void {
    if ($list === null) {
        return;
    }
    $html[] = "</" . $list . ">";
    $list = null;
};

$flushTable = function () use (&$html, &$table): void {
    if (!$table) {
        return;
    }
    $html[] = "<table>";
    foreach ($table as $index => $row) {
        if ($index === 1 && preg_match("/^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)+\|?\s*$/", $row)) {
            continue;
        }
        $cells = array_map("trim", explode("|", trim($row, "|")));
        $tag = ($index === 0) ? "th" : "td";
        $html[] = "<tr>" . implode("", array_map(fn($cell) => "<$tag>" . lf_inline($cell) . "</$tag>", $cells)) . "</tr>";
    }
    $html[] = "</table>";
    $table = [];
};

foreach ($lines as $line) {
    if (preg_match("/^#{1,3}\s+(.+)$/", $line, $m)) {
        $flushParagraph();
        $flushList();
        $flushTable();
        $level = strspn($line, "#");
        $title = trim($m[1]);
        $id = lf_slug($title, $used);
        $toc[] = [$level, $title, $id];
        $html[] = "<h$level id=\"$id\">" . lf_inline($title) . "</h$level>";
        continue;
    }

    if (trim($line) === "") {
        $flushParagraph();
        $flushList();
        $flushTable();
        continue;
    }

    if (str_starts_with(trim($line), "|")) {
        $flushParagraph();
        $flushList();
        $table[] = $line;
        continue;
    }

    if (preg_match("/^\s*-\s+(.+)$/", $line, $m)) {
        $flushParagraph();
        $flushTable();
        if ($list !== "ul") {
            $flushList();
            $html[] = "<ul>";
            $list = "ul";
        }
        $html[] = "<li>" . lf_inline(trim($m[1])) . "</li>";
        continue;
    }

    if (preg_match("/^\s*[0-9]+\.\s+(.+)$/", $line, $m)) {
        $flushParagraph();
        $flushTable();
        if ($list !== "ol") {
            $flushList();
            $html[] = "<ol>";
            $list = "ol";
        }
        $html[] = "<li>" . lf_inline(trim($m[1])) . "</li>";
        continue;
    }

    $flushList();
    $flushTable();
    $paragraph[] = trim($line);
}

$flushParagraph();
$flushList();
$flushTable();

$tocHtml = ["<nav id=\"TOC\"><h2>Inhalt</h2><ul>"];
foreach ($toc as [$level, $title, $id]) {
    if ($level <= 3) {
        $class = "toc-level-" . $level;
        $tocHtml[] = "<li class=\"$class\"><a href=\"#$id\">" . lf_inline($title) . "</a></li>";
    }
}
$tocHtml[] = "</ul></nav>";

$document = "<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n" .
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n" .
    "<title>LeitnerFlow Benutzer-Dokumentation</title>\n" .
    "<link rel=\"stylesheet\" href=\"user-doc.css\">\n</head>\n<body>\n" .
    implode("\n", $tocHtml) . "\n<main>\n" . implode("\n", $html) . "\n</main>\n</body>\n</html>\n";

file_put_contents($target, $document);
' "${SOURCE}" "${TARGET}"

echo "Built ${TARGET} with PHP fallback"
